import { CdkTextareaAutosize } from '@angular/cdk/text-field';
import {
  ChangeDetectionStrategy,
  Component,
  Directive,
  ElementRef,
  Provider,
  booleanAttribute,
  computed,
  forwardRef,
  inject,
  input,
  model,
  output,
  signal,
} from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import { CsButtonDirective } from '../core/foundations/cs-button.directive';
import { CsControlBase } from '../core/platform/cs-control-base.class';
import { CsIdService } from '../core/platform/cs-id.service';
import { CsLocalizationService } from '../core/platform/cs-localization.service';
import { FileEntry } from './file-entry.interface';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'cs-file-summary',
  templateUrl: './file-summary.component.html',
  styleUrl: './file-summary.component.scss',
})
export class FileSummaryComponent {
  readonly files = input.required<readonly FileEntry[]>();
  readonly removed = output<string>();
}

html:
@for (entry of files(); track entry.id) {
  <div>
    <span>{{ entry.file.name }}</span
    ><progress [value]="entry.progress ?? 0" max="100"></progress
    ><button type="button" (click)="removed.emit(entry.id)">Remove</button>
  </div>
}
